const D = { energy:.6, density:.5, scale:1, hue:44, speed:1, spread:.5, x:.12, y:.06, style:'volumetric', act:'dawn', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), lrp=(a,b,t)=>a+(b-a)*t, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360), st=P.style;
const vol=st==='volumetric', cath=st==='cathedral', crep=st==='crepuscular', scan=st==='scanline', blue=st==='blueprint';
const en=clp(P.energy,0,1), dens=clp(P.density,0,1), spread=clp(P.spread,0,1), spd=P.speed;
// strength follows musical intensity + audio, over a live-carrying baseline
const strength = clp(0.35 + 0.5*K.intensity + 0.25*K.swell + 0.35*A.rms + 0.2*K.pulse, 0, 1.4) * (0.4+0.8*en);

// ---- act dramaturgy ----
let bright=1, swingA=1, occl=0;
if(P.act==='dawn'){ bright=0.35+0.65*(0.5+0.5*Math.sin(K.t*0.02-1.2)); }          // slow brighten/dim cycle
else if(P.act==='flicker'){ occl=Math.max(0,Math.sin(K.t*0.5)*Math.sin(K.t*0.17)); bright=1-0.55*occl; swingA=1.3; } // clouds pass
else if(P.act==='noon'){ bright=1.05; swingA=0.6; }

// source corner (P.x,P.y) — beams fan outward from it
const sx=P.x*W, sy=P.y*Hh;
// central emission angle points from source toward opposite side of canvas
const baseAng=Math.atan2((Hh*0.62-sy),(W*0.5-sx));
const swing=Math.sin(K.t*0.06*spd)*0.16*swingA + Math.sin(K.t*0.021+1.3)*0.06; // slow sway, real-time
const fan = lrp(0.25,1.25,spread);                 // total angular spread of the fan
const NR = Math.max(3, Math.round(lrp(4,16,dens)));
const rayLen = Math.hypot(W,Hh)*1.15;

if(S.seedUsed!==P.seed || S.NR!==NR){
  S.seedUsed=P.seed; S.NR=NR; S.ray=[]; S.mote=[];
  for(let i=0;i<NR;i++) S.ray.push({ off:(i/(NR-1)-0.5), w:0.5+fr(i*3.1+1), fl:fr(i*5.7+2)*TAU, sp:0.5+fr(i*7.3+3), hj:(fr(i*2.2+4)-0.5)*20 });
  for(let i=0;i<160;i++) S.mote.push({ a:fr(i*1.7+9), d:fr(i*3.3+10), sp:0.3+fr(i*5.9+11), ph:fr(i*7.1+12)*TAU, sz:0.4+fr(i*2.6+13) });
}

const oldOp=drawingContext.globalCompositeOperation;

// beam color by style
function beamCol(hj,f){
  if(cath){ const hh=md(H+hj*3+ f*140,360); return [hh, 75, 100]; }   // stained glass — saturated, hue varies per beam
  if(blue){ return [205, 55, 100]; }
  if(crep){ return [md(H+hj*0.5,360), lrp(55,20,f), 100]; }
  return [md(H+hj,360), lrp(45,12,f), 100];                             // volumetric warm
}

// ---- draw shafts ----
if(blue){
  // schematic ray diagram: thin construction lines + angle arc + source node (abstract)
  stroke(205,55,100, clp(45+40*strength,0,90)); strokeWeight(Math.max(1,u*0.0016)); noFill();
  for(let i=0;i<NR;i++){ const R=S.ray[i]; const ang=baseAng+swing+R.off*fan;
    const ex=sx+Math.cos(ang)*rayLen, ey=sy+Math.sin(ang)*rayLen;
    // dashed
    const dn=26; for(let d=0;d<dn;d++){ if(d%2) continue; const t0=d/dn,t1=(d+1)/dn; line(lrp(sx,ex,t0),lrp(sy,ey,t0),lrp(sx,ex,t1),lrp(sy,ey,t1)); } }
  // angle arc + source
  noFill(); stroke(205,60,100,70); arc(sx,sy,u*0.3,u*0.3, baseAng+swing-fan*0.5, baseAng+swing+fan*0.5);
  noStroke(); fill(205,60,100,90); circle(sx,sy,u*0.02);
} else {
  blendMode(scan?SCREEN:ADD);
  noStroke();
  for(let i=0;i<NR;i++){
    const R=S.ray[i];
    const ang=baseAng+swing+R.off*fan;
    const flick=0.6+0.4*Math.sin(K.t*(0.5+R.sp*0.8)*spd+R.fl)+0.15*Math.sin(K.t*1.7+R.fl*2);
    const amp=strength*bright*flick*(0.5+0.7*R.w);
    if(amp<=0.02) continue;
    // beam as a long thin triangle-ish quad widening away from source
    const halfW0=u*0.006*(0.5+R.w);
    const halfW1=u*lrp(0.02,0.09,spread)*(0.5+R.w)*(cath?0.6:1);
    const perpAng=ang+Math.PI/2;
    const px=Math.cos(perpAng), py=Math.sin(perpAng);
    const ex=sx+Math.cos(ang)*rayLen, ey=sy+Math.sin(ang)*rayLen;
    // layered translucent slices for soft volumetric falloff
    const layers=cath?1:3;
    for(let L=0;L<layers;L++){
      const lw=lrp(1,0.35,L/Math.max(1,layers-1));
      const col=beamCol(R.hj, L/layers);
      const a=clp((cath?26:12)*amp*lw,0,cath?30:26);
      fill(col[0], cath?col[1]:clp(col[1]-L*6,0,100), 100, a);
      const w0=halfW0*lw, w1=halfW1*lw;
      quad(sx-px*w0, sy-py*w0, sx+px*w0, sy+py*w0, ex+px*w1, ey+py*w1, ex-px*w1, ey-py*w1);
    }
    if(cath){
      // stained-glass leaded edge
      stroke(0,0,10,20*amp); strokeWeight(Math.max(0.6,u*0.0012)); noFill();
      line(sx-px*halfW1, sy-py*halfW1, ex-px*halfW1, ey-py*halfW1);
      line(sx+px*halfW1, sy+py*halfW1, ex+px*halfW1, ey+py*halfW1);
      noStroke();
    }
  }
  blendMode(BLEND);
}

// ---- source flare bloom ----
if(!blue){
  blendMode(ADD); noStroke();
  const fr0=u*(0.05+0.14*spread)*(0.7+0.5*strength*bright);
  const fc= cath?[md(H+40,360),40,100]:[md(H,360),cath?40:22,100];
  for(let r=5;r>0;r--){ const tt=r/5; fill(fc[0],fc[1],100, clp(20*(1-tt)*(1-tt)*strength*bright,0,30)); ellipse(sx,sy,fr0*tt*2,fr0*tt*2); }
  blendMode(BLEND);
}

// ---- dust motes drifting inside the light cone (continuous, real-time) ----
if(!blue){
  blendMode(scan?BLEND:ADD); noStroke();
  const coneA0=baseAng+swing-fan*0.5, coneA1=baseAng+swing+fan*0.5;
  const nM=Math.round(160*clp(0.3+dens,0,1));
  for(let i=0;i<nM;i++){
    const M=S.mote[i];
    const ang=lrp(coneA0,coneA1,M.a);
    // drift outward along the shaft, loop
    const life=frc(M.d + K.t*0.03*M.sp*spd);
    const dist=life*rayLen*0.9 + u*0.05;
    const wob=Math.sin(K.t*0.4*M.sp+M.ph)*u*0.02;
    const perpAng=ang+Math.PI/2;
    const mx=sx+Math.cos(ang)*dist+Math.cos(perpAng)*wob;
    const my=sy+Math.sin(ang)*dist+Math.sin(perpAng)*wob;
    const twk=0.4+0.6*Math.sin(K.t*(1.5+M.sp*2)+M.ph);
    const a=clp((1-life)*strength*bright*(0.5+twk)*35,0,45)*(0.6+A.treble*0.8);
    const sz=u*0.0028*M.sz*(0.6+twk);
    const col= cath?[md(H+M.a*120,360),40,100]:[md(H+M.ph*3,360),15,100];
    fill(col[0],col[1],col[2],a);
    circle(mx,my,sz);
  }
  blendMode(BLEND);
}

// ---- scanline style overlay (retro CRT banding — abstract) ----
if(scan){
  blendMode(MULTIPLY);
  stroke(0,0,0,40); strokeWeight(1);
  const off=md(K.t*u*0.15,4);
  for(let y=-off;y<Hh;y+=4) line(0,y,W,y);
  blendMode(SCREEN);
  // rolling bright band
  const bandY=md(K.t*u*0.2,Hh*1.2)-Hh*0.1;
  noStroke(); fill(md(H,360),30,100,10*strength); rect(0,bandY-u*0.05,W,u*0.1);
  blendMode(BLEND);
}

blendMode(BLEND); drawingContext.globalCompositeOperation=oldOp; drawingContext.shadowBlur=0; noStroke();
